#!/usr/bin/env python3
"""Build Figure 3c and 3f (Twitter), the combined figure and the comparison with the paper.

usage: make_figures.py            (run from the repo root, after the simulations)

reads   results/raw/twitter/*.log, paper/fig3_paper_values.csv
writes  results/twitter.csv                     one row per trace x size x algorithm
        fig3<p>/fig3<p>.png                     one panel, paper style (p = c, f)
        fig3<p>/stats.csv                       the plotted numbers (ours)
        fig3<p>/comparison.csv                  ours vs paper, per algorithm
        fig3_combined.png                       3c and 3f next to each other
        results/summary.md                      the pattern checks for both panels
"""
import glob
import os
import sys

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import pandas as pd

sys.path.insert(0, os.path.dirname(__file__))
from parse_logs import parse  # noqa: E402
from plot_fig3 import FILL, ORDER, stats  # noqa: E402

PANELS = {  # panel: (dataset, size, our title, paper title)
    "c": ("twitter", "large", "Twitter", "Twitter, 54 traces"),
    "f": ("twitter", "small", "Twitter", "Twitter, 54 traces"),
}
SIZE_TXT = {"large": "large cache (10%)", "small": "small cache (0.1%)"}


def load(ds):
    rows = []
    for p in sorted(glob.glob(f"results/raw/{ds}/*.log")):
        for r in parse(p):
            r["dataset"] = ds
            rows.append(r)
    df = pd.DataFrame(rows)
    if len(df):
        df.to_csv(f"results/{ds}.csv", index=False)
    return df


def draw(ax, st, size, title):
    bxp = [dict(label=r.algo, whislo=r.p10, q1=r.p25, med=r.median, q3=r.p75, whishi=r.p90,
                mean=r.mean, fliers=[]) for r in st.itertuples()]
    ax.bxp(bxp, showmeans=True, showfliers=False, patch_artist=True, widths=0.6,
           boxprops=dict(facecolor=FILL[size], edgecolor="#333333", linewidth=0.8),
           medianprops=dict(color="#333333", linewidth=0.8),
           whiskerprops=dict(color="#333333", linewidth=0.8),
           capprops=dict(color="#333333", linewidth=0.8),
           meanprops=dict(marker="v", markerfacecolor="#2E7D32", markeredgecolor="#C62828",
                          markersize=6))
    ax.set_ylabel("Miss Ratio Reduction\nfrom FIFO", fontsize=9)
    ax.set_xticks(range(1, len(ORDER) + 1))
    ax.set_xticklabels(ORDER, rotation=45, ha="right", fontsize=8)
    ax.tick_params(axis="y", labelsize=8)
    ax.grid(axis="y", color="#DDDDDD", linewidth=0.6)
    ax.grid(axis="x", color="#EEEEEE", linewidth=0.6)
    ax.set_axisbelow(True)
    ax.set_xlabel(title, fontsize=9)


def rank(series):
    return series.rank(ascending=False, method="min").astype(int)


def compare(st, paper):
    m = st.set_index("algo")[["mean", "median", "p25", "p75", "p10", "p90"]].join(
        paper.set_index("algo")[["mean", "median", "p25", "p75", "p10", "p90"]],
        lsuffix="_ours", rsuffix="_paper").reindex(ORDER)
    m["rank_mean_ours"] = rank(m["mean_ours"])
    m["rank_mean_paper"] = rank(m["mean_paper"])
    return m.reset_index()


def checks(cmp, panel):
    """The qualitative statements a reader takes from each panel, checked on both."""
    out = []
    o, p = cmp.set_index("algo")["mean_ours"], cmp.set_index("algo")["mean_paper"]
    rho = pd.Series(o).rank().corr(pd.Series(p).rank())
    out.append(("Spearman rank correlation of the 11 means (ours vs paper)", f"{rho:.2f}", ""))
    for name, s in (("ours", o), ("paper", p)):
        top = s.sort_values(ascending=False).index[:3].tolist()
        out.append((f"top 3 by mean ({name})", ", ".join(top), ""))
    out.append(("SIEVE rank by mean (1 = best of 11)",
                f"{int(rank(o)['SIEVE'])}", f"{int(rank(p)['SIEVE'])}"))
    out.append(("B-LRU worst by mean", str(o.idxmin() == "B-LRU"), str(p.idxmin() == "B-LRU")))
    sv = cmp.set_index("algo")
    out.append(("SIEVE mean above CLOCK and LRU",
                str(o["SIEVE"] > o["CLOCK"] and o["SIEVE"] > o["LRU"]),
                str(p["SIEVE"] > p["CLOCK"] and p["SIEVE"] > p["LRU"])))
    out.append(("TinyLFU P10 below 0", str(sv.loc["TinyLFU", "p10_ours"] < 0),
                str(sv.loc["TinyLFU", "p10_paper"] < 0)))
    return out


def main():
    paper = pd.read_csv("paper/fig3_paper_values.csv")
    data = {"twitter": load("twitter")}
    fig, axes = plt.subplots(1, 2, figsize=(9, 3.8), dpi=200)
    summary = ["# Figure 3: replication vs paper (generated by scripts/make_figures.py)\n"]
    for i, (pn, (ds, size, title, ptitle)) in enumerate(PANELS.items()):
        df = data[ds]
        ax = axes[i]
        if not len(df):
            ax.set_axis_off()
            continue
        d = df[df["size"] == size]
        st = stats(d)
        n = int(st.n.iloc[0])
        os.makedirs(f"fig3{pn}", exist_ok=True)
        st.round(4).to_csv(f"fig3{pn}/stats.csv", index=False)
        cap = f"({pn}) {title}, {SIZE_TXT[size]}, {n} traces"
        draw(ax, st, size, cap)
        f1, a1 = plt.subplots(figsize=(4.6, 3.6), dpi=200)
        draw(a1, st, size, cap)
        f1.tight_layout()
        f1.savefig(f"fig3{pn}/fig3{pn}.png")
        plt.close(f1)

        cmp = compare(st, paper[paper.panel == pn])
        cmp.round(4).to_csv(f"fig3{pn}/comparison.csv", index=False)
        summary.append(f"\n## Panel ({pn}): {title} vs paper {ptitle}, {SIZE_TXT[size]}\n")
        summary.append(f"Traces: {n} (paper: {ptitle.split(', ')[1]})\n")
        summary.append("| check | ours | paper |\n|---|---|---|")
        for c, a_, b_ in checks(cmp, pn):
            summary.append(f"| {c} | {a_} | {b_} |")
        summary.append("\n| algorithm | mean ours | mean paper | median ours | median paper |"
                       " rank ours | rank paper |\n|---|---|---|---|---|---|---|")
        for r in cmp.itertuples():
            summary.append(f"| {r.algo} | {r.mean_ours:.3f} | {r.mean_paper:.3f} | "
                           f"{r.median_ours:.3f} | {r.median_paper:.3f} | "
                           f"{r.rank_mean_ours} | {r.rank_mean_paper} |")
    fig.tight_layout()
    fig.savefig("fig3_combined.png")
    open("results/summary.md", "w").write("\n".join(summary) + "\n")
    print("\n".join(summary))


if __name__ == "__main__":
    main()
